# Owned disposable fixtures only. No real game process or DLL is executed.
param([Parameter(Mandatory=$true)][string]$Work,[Parameter(Mandatory=$true)][string]$Module)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
Import-Module $Module -Force
$m=Get-Module Supermoon.Setup
& $m {
 param($Work)
 $script:TestRoot=[IO.Path]::GetFullPath($Work);[void][IO.Directory]::CreateDirectory($script:TestRoot)
 $script:Results=New-Object Collections.ArrayList
 function Assert($Condition,$Message='Assertion failed'){if(-not $Condition){throw $Message}}
 function Refuses([scriptblock]$Code,$Text=''){$caught=$false;try{& $Code | Out-Null}catch{$caught=$true;if($Text){Assert ($_.Exception.Message -like ('*'+$Text+'*')) $_.Exception.Message}};Assert $caught 'Operation unexpectedly succeeded'}
 function Put($Rel,$Data){$p=Join-Path $script:C.Game $Rel;[SupermoonSetup.Native]::NoReparse($p);[void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($p));[IO.File]::WriteAllBytes($p,[byte[]]$Data)}
 function Bytes($Text){return ,([Text.Encoding]::UTF8.GetBytes($Text))}
 function Fresh {
  $script:Case=Join-Path $script:TestRoot ([guid]::NewGuid().ToString('N'));$g=Join-Path $script:Case 'persistent/game & é ! % ^ (test) [1]'
  [void][IO.Directory]::CreateDirectory($g);$script:Exe=Bytes 'OWNED EXE DATA NEVER EXECUTE';$script:Old=Bytes 'OWNED LEGACY BANK'
  $script:Desired=@{proxy=(Bytes 'OWNED PROXY');payload=(Bytes 'OWNED PAYLOAD');bank=(Bytes 'OWNED BANK');marker=$script:Marker}
  $recipe=@{version='owned-test-1';game_executable_bytes=$script:Exe.Length;game_executable_sha256=(Get-SMIdentity $script:Exe)['sha256'];DLLs=@{'winmm.dll'=(Get-SMIdentity $script:Desired.proxy);'supermoon_playlist.dll'=(Get-SMIdentity $script:Desired.payload)}}
  $plan=@{output_bytes=$script:Desired.bank.Length;output_sha256=(Get-SMIdentity $script:Desired.bank)['sha256']}
  $script:C=New-SMContext $g $recipe $plan;$script:MenuSha=(Get-SMIdentity $script:Old)['sha256'];Put 'Binaries/NMS.exe' $script:Exe
  $script:Personal=@{'Binaries/Supermoon/playlist.ini'=(Bytes 'PERSONAL INI');'Binaries/Supermoon/Music/personal.wav'=(Bytes 'PERSONAL MUSIC');'Binaries/Supermoon/Cache/owned.pcm'=(Bytes 'PERSONAL CACHE');'Binaries/Supermoon/State/owned'=(Bytes 'PERSONAL STATE');'Binaries/Supermoon/diagnostics.log'=(Bytes 'PERSONAL DIAGNOSTICS');'Binaries/unrelated.dll'=(Bytes 'OTHER DLL');'Binaries/SETTINGS/GCMODSETTINGS.MXML'=(Bytes 'PERSONAL MOD SETTINGS');'GAMEDATA/MODS/OtherMod/keep'=(Bytes 'OTHER MOD');'GAMEDATA/PCBANKS/keep'=(Bytes 'NATIVE ARCHIVE SENTINEL')}
  foreach($k in $script:Personal.Keys){Put $k $script:Personal[$k]}
  $script:ExternalMusic=Join-Path $script:Case 'external-personal-music.wav';[IO.File]::WriteAllBytes($script:ExternalMusic,(Bytes 'EXTERNAL PERSONAL MUSIC'))
  $script:Temp=Join-Path $script:Case 'TEMP';[void][IO.Directory]::CreateDirectory($script:Temp);$env:TEMP=$script:Temp;$env:TMP=$script:Temp
  function script:Invoke-SMCheckpoint($Stage){}
 }
 function Intact {foreach($k in $script:Personal.Keys){Assert (Test-SMEqual (Get-SMCurrent (Join-Path $script:C.Game $k)) (Get-SMIdentity $script:Personal[$k])) ('Personal file changed: '+$k)};Assert (Test-SMEqual (Get-SMCurrent (Join-Path $script:C.Game 'Binaries/NMS.exe')) (Get-SMIdentity $script:Exe)) 'Executable changed';Assert(Test-SMEqual (Get-SMCurrent $script:ExternalMusic) (Get-SMIdentity (Bytes 'EXTERNAL PERSONAL MUSIC'))) 'External music changed'}
 function Install { $r=Invoke-SMMutation $script:C 'install' $script:Desired;Intact;return $r }
 function Baseline($Bank=$true){foreach($k in $script:Keys){if($k -ne 'bank' -or $Bank){Put $script:Paths[$k] $script:Desired[$k]}}}
 function Record {Get-SMRecord $script:C $null}
 function Case($Name,[scriptblock]$Code){Fresh;try{& $Code;Intact;[void]$script:Results.Add(@{case=$Name;result='PASS'});Write-Host ($Name+' PASS')}catch{[void]$script:Results.Add(@{case=$Name;result='FAIL';error=$_.ToString()});Write-Host ($Name+' FAIL '+$_.Exception.Message)} }
 Case '01-clean-defaults' {$p=Join-Path $C.Game 'Binaries/Supermoon/playlist.ini';[IO.File]::Delete($p);$Personal.Remove('Binaries/Supermoon/playlist.ini');Assert ((Install).result -eq 'verified');Assert (-not[IO.File]::Exists($p))}
 Case '02-update-first-prior-preserved' {Baseline $false;Put $Paths.bank $Old;$a=Install;$r=Record;$pin=Get-SMCurrent (Join-Path $r.Folder 'manifest.json');$b=Install;Assert ($a.record -eq $b.record);Assert (Test-SMEqual $pin (Get-SMCurrent (Join-Path $r.Folder 'manifest.json')));Assert(Test-SMEqual $r.Manifest['before']['bank'] (Get-SMIdentity $Old))}
 Case '03-current-install-record' {Baseline;$r=Install;Assert ((Get-SMStatus $C).journal['phase'] -eq 'verified');Assert(Test-SMEqual (Record).Manifest['before'] $C.Expected)}
 Case '04-resume-no-stage-or-temp' {$a=Install;$r=Record;[IO.File]::WriteAllText((Join-Path $Temp 'discard'),'TEMP');[IO.File]::Delete((Join-Path $Temp 'discard'));Assert ((Invoke-SMMutation $C 'resume').result -eq 'verified');Assert ($a.record -eq (Record).Manifest['record'])}
 Case '05-rollback-retry-reinstall' {$a=Install;Assert ((Invoke-SMMutation $C 'rollback').result -eq 'rolled_back');Invoke-SMMutation $C 'rollback' | Out-Null;$b=Install;Assert($a.record -ne $b.record);Assert ((Get-SMStatus $C).records.Count -eq 2)}
 Case '06-qualified-prior-bank-absence' {Baseline $false;$before=Get-SMObserved $C;Install|Out-Null;Invoke-SMMutation $C 'rollback'|Out-Null;Assert(Test-SMEqual $before (Get-SMObserved $C))}
 Case '07-unqualified-legacy-rollback-refused' {Baseline $false;Put $Paths.bank $Old;Install|Out-Null;Refuses {Invoke-SMMutation $C 'rollback'} 'not qualified';Assert ((Invoke-SMMutation $C 'disable').result -eq 'disabled')}
 Case '08-foreign-program-bank-marker' {foreach($k in $Keys){Put $Paths[$k] (Bytes 'FOREIGN');Refuses {Install} 'Unknown installed';[IO.File]::Delete((Get-SMTarget $C $k))}}
 Case '09-corrupt-candidate' {$bad=@{};foreach($k in $Keys){$bad[$k]=$Desired[$k]};$bad.proxy=Bytes 'BAD';Refuses {Invoke-SMMutation $C 'install' $bad} 'Candidate';$bad.payload=$null;Refuses {Invoke-SMMutation $C 'install' $bad}}
 Case '10-unsupported-game-disable-only' {Install|Out-Null;$script:Exe=Bytes 'UNSUPPORTED';Put 'Binaries/NMS.exe' $script:Exe;Refuses {Invoke-SMMutation $C 'resume'} 'Unsupported';Refuses {Invoke-SMMutation $C 'rollback'} 'Unsupported';Assert ((Invoke-SMMutation $C 'disable').result -eq 'disabled')}
 Case '11-unknown-current-blocks-recovery' {Install|Out-Null;Put $Paths.payload (Bytes 'FOREIGN');foreach($a in @('resume','rollback','disable')){Refuses {Invoke-SMMutation $C $a} 'Unknown current'}}
 Case '12-corrupt-new-backup-manifest' {Install|Out-Null;$r=Record;$p=Join-Path $r.Folder 'new-0.bin';[IO.File]::WriteAllText($p,'BAD');Refuses {Invoke-SMMutation $C 'resume'} 'backup';Assert ((Get-SMStatus $C).result -eq 'CORRUPT_RECORD_REFUSED')}
 Case '13-corrupt-prior-backup' {Baseline;Install|Out-Null;$r=Record;[IO.File]::WriteAllText((Join-Path $r.Folder 'prior-0.bin'),'BAD');Refuses {Invoke-SMMutation $C 'rollback'} 'backup'}
 Case '14-saved-replacement-rechecked' {Install|Out-Null;$r=Record;function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'after_remove:marker'){[IO.File]::WriteAllText((Join-Path (Record).Folder 'new-1.bin'),'BAD')}};Refuses {Invoke-SMMutation $C 'resume'} 'Saved replacement'}
 Case '15-unreadable-journal-recovery' {Install|Out-Null;$r=Record;[IO.File]::WriteAllText((Join-Path $r.Folder 'journal.json'),'{');Assert ((Get-SMStatus $C).journal.phase -eq 'UNREADABLE');Assert ((Invoke-SMMutation $C 'resume').result -eq 'verified')}
 Case '16-selector-explicit-record' {$a=Install;[IO.File]::WriteAllText((Join-Path $C.Store 'ACTIVE.json'),'BAD');Refuses {Invoke-SMMutation $C 'resume'};Assert ((Invoke-SMMutation $C 'resume' $null $a.record).result -eq 'verified')}
 Case '17-path-bound-record' {Install|Out-Null;$r=Record;$manifest=$r.Manifest;$manifest['game']=$C.Game+'-other';$raw=ConvertTo-SMBytes $manifest;[IO.File]::WriteAllBytes((Join-Path $r.Folder 'manifest.json'),$raw);$sha=(Get-SMIdentity $raw)['sha256'];[IO.File]::WriteAllText((Join-Path $r.Folder 'manifest.sha256'),$sha+"`n",[Text.Encoding]::ASCII);Write-SMJson (Join-Path $C.Store 'ACTIVE.json') @{record=$manifest['record'];manifest_sha256=$sha};Refuses {Invoke-SMMutation $C 'resume'} 'target/schema'}
 Case '18-duplicate-json-and-policy-mismatch' {Install|Out-Null;$r=Record;$C.Recipe.version='WRONG VERSION';Refuses {Invoke-SMMutation $C 'resume'} 'policy mismatch';Refuses {[SupermoonSetup.Json]::Parse((Bytes '{"a":1,"a":2}'))};Refuses {[SupermoonSetup.Json]::Parse((Bytes '{"a":1,"A":2}'))};Refuses {[SupermoonSetup.Json]::Parse((Bytes '{"x":{"a":1,"a":2}}'))}}
 Case '19-status-read-only' {Install|Out-Null;$before=@{};foreach($p in [IO.Directory]::EnumerateFiles($C.Game,'*',[IO.SearchOption]::AllDirectories)){$before[$p]=Get-SMCurrent $p};Get-SMStatus $C|Out-Null;foreach($p in $before.Keys){Assert(Test-SMEqual $before[$p] (Get-SMCurrent $p))}}
 Case '20-temp-recovery-refused' {$env:TEMP=$Case;$env:TMP=$Case;Refuses {Install} 'outside TEMP'}
 Case '21-backup-failure' {function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'before_backup:bank'){throw 'OWNED BACKUP FAILURE'}};Refuses {Install} 'BACKUP';Assert ($null -eq (Get-SMCurrent (Get-SMTarget $C 'proxy')))}
 Case '22-record-failure-before-selector' {function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'before_backup:marker'){[IO.Directory]::CreateDirectory((Join-Path $C.Store 'ACTIVE.json'))|Out-Null}};Refuses {Install};Assert ($null -eq (Get-SMCurrent (Get-SMTarget $C 'bank')))}
 Case '23-replace-failure-retry-keeps-prior' {function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'before_replace:bank'){throw 'OWNED REPLACE FAILURE'}};Refuses {Install} 'incomplete';$a=Get-SMActive $C;function script:Invoke-SMCheckpoint($Stage){};Assert ((Install).record -eq $a['record'])}
 Case '24-post-bank-failure-status' {function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'after_replace:bank'){throw 'OWNED AFTER BANK'}};Refuses {Install} 'bank may already';$s=Get-SMStatus $C;Assert ($s.files.bank -eq 'candidate');Assert ($s.journal['phase'] -eq 'failed')}
 Case '25-post-commit-corrupt-target' {function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'after_replace:bank'){Put $Paths.bank (Bytes 'CORRUPTION')}};Refuses {Install};Assert ((Get-SMStatus $C).result -eq 'UNKNOWN_CURRENT_REFUSED');Refuses {Invoke-SMMutation $C 'resume'} 'Unknown current'}
 Case '26-final-journal-failure' {function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'before_verified_journal'){throw 'OWNED FINAL JOURNAL FAILURE'}};Refuses {Install} 'incomplete';Assert(Test-SMEqual (Get-SMObserved $C) $C.Expected);Assert ((Get-SMStatus $C).journal['phase'] -eq 'failed')}
 Case '27-scratch-write-failure' {function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'before_scratch:bank'){throw 'OWNED SCRATCH WRITE FAILURE'}};Refuses {Install} 'SCRATCH';$r=Record;Assert(Test-SMEqual (Get-SMCurrent (Join-Path $r.Folder 'new-2.bin')) $C.Expected.bank);Assert($null -eq (Get-SMCurrent (Get-SMTarget $C 'bank')))}
 Case '28-real-sharing-violation-recoverable' {Install|Out-Null;$p=Get-SMTarget $C 'payload';$h=[IO.File]::Open($p,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{Refuses {Invoke-SMMutation $C 'disable'} 'incomplete'}finally{$h.Dispose()};Assert ((Invoke-SMMutation $C 'disable').result -eq 'disabled')}
 Case '29-exclusive-writer-lock' {$h=[SupermoonSetup.Native]::WriterLock((Join-Path $C.Game '.supermoon-install.lock'));try{Refuses {Install} 'writer'}finally{$h.Dispose()};Install|Out-Null}
 Case '30-reparse-paths-refused' {$outside=Join-Path $Case 'outside';[void][IO.Directory]::CreateDirectory($outside);$link=Join-Path $C.Game 'junction';& $env:SystemRoot\System32\cmd.exe /d /c mklink /J $link $outside | Out-Null;Assert ($LASTEXITCODE -eq 0);Refuses {New-SMContext $link $C.Recipe $C.Plan} 'Reparse';Refuses {[SupermoonSetup.Native]::Read((Join-Path $link 'missing'),100)} 'Reparse'}
 Case '31-path-switch-after-preparation' {function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'prepared'){$parent=Join-Path $C.Game 'GAMEDATA/MODS';[IO.Directory]::Move($parent,$parent+'-owned-old');$outside=Join-Path $Case 'outside';[void][IO.Directory]::CreateDirectory($outside);& $env:SystemRoot\System32\cmd.exe /d /c mklink /J $parent $outside|Out-Null}};Refuses {Install} 'Reparse';$parent=Join-Path $C.Game 'GAMEDATA/MODS';Assert($parent.StartsWith($script:TestRoot));Assert(([IO.File]::GetAttributes($parent) -band [IO.FileAttributes]::ReparsePoint) -ne 0);[IO.Directory]::Delete($parent);[IO.Directory]::Move($parent+'-owned-old',$parent)}
 Case '32-changed-destination-before-final-check' {function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'before_replace:proxy'){Put $Paths.payload (Bytes 'FOREIGN')}};Refuses {Install} 'Destination changed';Assert ((Get-SMStatus $C).result -eq 'UNKNOWN_CURRENT_REFUSED')}
 Case '33-uncooperative-final-race-limit' {function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'before_replace:bank'){Put $Paths.bank (Bytes 'NONCOOPERATING WRITER')}};Install|Out-Null;Assert(Test-SMEqual (Get-SMCurrent (Get-SMTarget $C 'bank')) $C.Expected.bank)}
 Case '34-interruptions-resume-rollback' {foreach($stage in @('prepared','before_replace:bank','after_replace:bank','before_verified_journal','after_remove:marker')){Fresh;Baseline $false;$script:StopAt=$stage;function script:Invoke-SMCheckpoint($Stage){if($Stage -eq $script:StopAt){throw 'OWNED INTERRUPTION'}};Refuses {Install};function script:Invoke-SMCheckpoint($Stage){};Assert ((Invoke-SMMutation $C 'resume').result -eq 'verified');Assert ((Invoke-SMMutation $C 'rollback').result -eq 'rolled_back');Intact}}
 Case '35-no-live-ini-and-fixed-authority' {Install|Out-Null;Assert($Paths.Count -eq 4);Assert($Paths.Values -notcontains 'Binaries/Supermoon/playlist.ini');Refuses {Get-SMRecord $C '../escape'} 'valid selected';Refuses {[SupermoonSetup.Native]::PathName('C:\bad\..\path')};Refuses {[SupermoonSetup.Native]::PathName('C:\bad:file')};Refuses {[SupermoonSetup.Native]::PathName('C:\bad\NUL.txt')}}
 Case '36-missing-candidate-bank-refused' {$d=@{};foreach($k in $Keys){$d[$k]=$Desired[$k]};$d.bank=$null;Refuses {Invoke-SMMutation $C 'install' $d} 'Candidate'}
 Case '37-bank-patch-and-negative-inputs' {$native=New-Object byte[] 64;[Array]::Copy([BitConverter]::GetBytes([uint32]1234),0,$native,4,4);$out=[byte[]]$native.Clone();[Array]::Copy([BitConverter]::GetBytes([uint32]4321),0,$out,4,4);$plan=@{input_bytes=64;input_sha256=(Get-SMIdentity $native)['sha256'];output_bytes=64;output_sha256=(Get-SMIdentity $out)['sha256'];insertions=@();edits=@(@{offset=4;format='<I';expected=1234;value=4321})};Assert(Test-SMEqual (Get-SMIdentity (Convert-SMBank $native $plan)) (Get-SMIdentity $out));Refuses {Convert-SMBank (Bytes 'BAD') $plan};$plan.output_sha256='0'*64;Refuses {Convert-SMBank $native $plan} 'exact identity'}
 Case '38-real-process-snapshot-no-search' {$names=[SupermoonSetup.Native]::ProcessNames();Assert ($names.Count -gt 0);Put 'Binaries/tasklist.exe' (Bytes 'NEVER EXECUTE');Assert-SMClosed}
 Case '39-process-guard-fail-closed' {function script:Assert-SMClosed {throw 'OWNED INDETERMINATE PROCESS SNAPSHOT'};Refuses {Install} 'INDETERMINATE';Remove-Item Function:script:Assert-SMClosed;function script:Assert-SMClosed {$names=[SupermoonSetup.Native]::ProcessNames();if($names.Count -eq 0 -or @($names|Where-Object{[string]::IsNullOrWhiteSpace($_)-or $_ -ieq 'NMS.exe'}).Count){throw 'NMS running or indeterminate'}}}
 Case '40-hardlinks-refused' {Baseline;$link=Join-Path $C.Game 'owned-hardlink';& $env:SystemRoot\System32\cmd.exe /d /c mklink /H $link (Get-SMTarget $C 'proxy') | Out-Null;Assert($LASTEXITCODE -eq 0);Refuses {Get-SMObserved $C} 'hard link'}
 Case '41-other-loose-bank-conflict' {Put 'GAMEDATA/MODS/Foreign/audio/windows/init.bnk' (Bytes 'FOREIGN');Refuses {Assert-SMNoLooseConflict $C} 'Conflicting';Assert($null -eq (Get-SMCurrent (Get-SMTarget $C 'bank')))}
 Case '42-missing-backup' {Install|Out-Null;$r=Record;[IO.File]::Delete((Join-Path $r.Folder 'new-2.bin'));Refuses {Invoke-SMMutation $C 'resume'} 'backup'}
 Case '43-missing-manifest' {Install|Out-Null;$r=Record;[IO.File]::Delete((Join-Path $r.Folder 'manifest.json'));Assert ((Get-SMStatus $C).result -eq 'CORRUPT_RECORD_REFUSED')}
 Case '44-malformed-json-types' {Refuses {[SupermoonSetup.Json]::Parse((Bytes '{"x":01}'))};Refuses {[SupermoonSetup.Json]::Parse((Bytes '{"x":NaN}'))};Refuses {[SupermoonSetup.Json]::Parse((Bytes '{"x":1} trailing'))};Refuses {[SupermoonSetup.Json]::Parse(([byte[]]@(0xff,0xfe)))}}
 Case '45-unknown-lock-file-preserved' {Put '.supermoon-install.lock' (Bytes 'UNKNOWN LOCK CONTENT');Refuses {Install} 'size';Assert(Test-SMEqual (Get-SMCurrent (Join-Path $C.Game '.supermoon-install.lock')) (Get-SMIdentity (Bytes 'UNKNOWN LOCK CONTENT')))}
 Case '46-error-after-removing-current-marker' {Baseline;function script:Invoke-SMCheckpoint($Stage){if($Stage -eq 'after_remove:marker'){throw 'OWNED AFTER MARKER'}};Refuses {Install} 'incomplete';Assert($null -eq (Get-SMCurrent (Get-SMTarget $C 'marker')));function script:Invoke-SMCheckpoint($Stage){};Assert ((Invoke-SMMutation $C 'resume').result -eq 'verified')}
 Case '47-same-destination-final-precheck' {$script:ClosedCount=0;function script:Assert-SMClosed {$script:ClosedCount++;if($script:ClosedCount -eq 4){Put $Paths.proxy (Bytes 'FOREIGN FINAL DESTINATION')}};Refuses {Install} 'Destination changed before replacement';Assert ((Get-SMStatus $C).result -eq 'UNKNOWN_CURRENT_REFUSED');function script:Assert-SMClosed {$names=[SupermoonSetup.Native]::ProcessNames();if($names.Count -eq 0 -or @($names|Where-Object{[string]::IsNullOrWhiteSpace($_)-or $_ -ieq 'NMS.exe'}).Count){throw 'NMS running or indeterminate'}}}
 Case '48-record-types-not-coerced' {Install|Out-Null;$r=Record;$m=$r.Manifest;$m['schema']='1';$raw=ConvertTo-SMBytes $m;$sha=(Get-SMIdentity $raw)['sha256'];[IO.File]::WriteAllBytes((Join-Path $r.Folder 'manifest.json'),$raw);[IO.File]::WriteAllText((Join-Path $r.Folder 'manifest.sha256'),$sha+"`n",[Text.Encoding]::ASCII);Write-SMJson (Join-Path $C.Store 'ACTIVE.json') @{record=$m['record'];manifest_sha256=$sha};Refuses {Invoke-SMMutation $C 'resume'} 'target/schema';Assert (-not(Test-SMEqual $true 1));Assert (-not(Test-SMEqual @{bytes=1} @(@{bytes=1})))}
 $pass=@($script:Results | Where-Object {$_.result -eq 'PASS'}).Count;$fail=$script:Results.Count-$pass
 [IO.File]::WriteAllText((Join-Path $script:TestRoot 'RESULTS.json'),(ConvertTo-Json -InputObject @{powershell=$PSVersionTable.PSVersion.ToString();edition=$PSVersionTable.PSEdition;pass=$pass;fail=$fail;cases=@($script:Results)} -Depth 12),[Text.UTF8Encoding]::new($false))
 Write-Host ("Totals: $pass PASS, $fail FAIL");if($fail){exit 1}
 } $Work
